contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address addr1, address addr2) public payable {
        require(addr1 != addr2, "need two distinct addresses");
        bool reverted1;
        bool reverted2;
        bool revertedAfterInit;

        c.SetLogFile(addr1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }
        c.SetLogFile(addr2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        c.Initialized(); if (__ESBMC_reverted()) return;

        c.SetLogFile(addr1); bool __rev2 = __ESBMC_reverted(); if (__rev2) { revertedAfterInit = true; } else { revertedAfterInit = false; }

        assert(!reverted1 && !reverted2 && revertedAfterInit);
    }

    receive() external payable {}
}

