pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address addr1, address addr2) internal {
        vm.assume(addr1 != addr2);
        bool reverted1;
        bool reverted2;
        bool revertedAfterInit;
        try c.SetLogFile(addr1) { reverted1 = false; } catch { reverted1 = true; }
        try c.SetLogFile(addr2) { reverted2 = false; } catch { reverted2 = true; }
        try c.Initialized() {} catch { return; }
        try c.SetLogFile(addr1) { revertedAfterInit = false; } catch { revertedAfterInit = true; }
        assertTrue(!reverted1 && !reverted2 && revertedAfterInit);
    }

    function testFuzz_run(address addr1, address addr2) public {
        vm.assume(addr1.code.length == 0 && uint160(addr1) > 0xffff && addr1 != address(this) && addr1 != address(c) && addr1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr1 != 0x000000000000000000636F6e736F6c652e6c6f67 && addr1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(addr2.code.length == 0 && uint160(addr2) > 0xffff && addr2 != address(this) && addr2 != address(c) && addr2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr2 != 0x000000000000000000636F6e736F6c652e6c6f67 && addr2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(addr1, addr2);
    }

    receive() external payable {}
}
